import java.util.*;

class Solution {
  public int minimumSubstringsInPartition(String s) {
    int n = s.length();
    int[] dp = new int[n + 1];
    Arrays.fill(dp, n + 1);
    dp[0] = 0;
    for (int end = 1; end <= n; end++) {
      int[] count = new int[26];
      int min = Integer.MAX_VALUE, max = 0;
      for (int start = end - 1; start >= 0; start--) {
        int f = ++count[s.charAt(start) - 'a'];
        max = Math.max(max, f);
        min = Integer.MAX_VALUE;
        for (int c : count) if (c > 0) min = Math.min(min, c);
        if (min == max) dp[end] = Math.min(dp[end], dp[start] + 1);
      }
    }
    return dp[n];
  }
}
